// 從最低位往前加：不是 9 就直接 +1 回傳，是 9 就變 0 繼續進位
// 時間複雜度: O(n)，空間複雜度: O(1)（全部是 9 時為 O(n)）
function plusOne(digits) {
    for (let i = digits.length - 1; i >= 0; i--) {
        if (digits[i] < 9) {
            digits[i]++;
            return digits;
        }
        digits[i] = 0;
    }
    return [1, ...digits]; // 例如 999 → 1000
}

