class Solution {
    /**
     * 方法：從後往前處理進位
     * 時間複雜度: O(n)
     * 空間複雜度: O(n) - 最壞情況需要新陣列
     */
    public int[] plusOne(int[] digits) {
        int n = digits.length;

        // 從最後一位開始處理
        for (int i = n - 1; i >= 0; i--) {
            // 當前位加一
            digits[i]++;

            // 如果沒有進位，直接返回
            if (digits[i] < 10) {
                return digits;
            }

            // 有進位，當前位設為 0
            digits[i] = 0;
        }

        // 如果執行到這裡，說明所有位都是 9
        // 需要創建新陣列，長度 +1
        int[] result = new int[n + 1];
        result[0] = 1;
        // 其餘位默認為 0

        return result;
    }
}

